package com.smarthub.plus;
import android.content.Context;import okhttp3.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.TimeUnit;
/** Direct factory authentication; independent credentials, strict TLS and no credential redirects. */
final class FactoryClient {
 private static final OkHttpClient HTTP=new OkHttpClient.Builder().connectTimeout(6,TimeUnit.SECONDS).readTimeout(12,TimeUnit.SECONDS).callTimeout(18,TimeUnit.SECONDS).followRedirects(false).followSslRedirects(false).retryOnConnectionFailure(false).build();
 private static final String[] DISCOVERY={"https://bl.zzdss.com/balance/serverInfo/list","https://vvbbl.com/balance/serverInfo/list","https://zccxx.com/balance/serverInfo/list"};
 private static final Object AUTH=new Object();private final Context context;private JSONObject saved,identity;
 FactoryClient(Context c){context=c.getApplicationContext();}
 private JSONObject request(String url,String token,JSONObject body)throws Exception{return request(url,token,body,0);}
 private JSONObject request(String url,String token,JSONObject body,int redirects)throws Exception{HttpUrl parsed=HttpUrl.parse(url);if(parsed==null||!parsed.isHttps())throw new IOException("FACTORY_HTTPS_REQUIRED");String host="https://"+parsed.host();if(token!=null&&!token.isEmpty()&&(saved==null||!FactoryProtocol.allowedOrigin(saved,host)))throw new IOException("FACTORY_SESSION_HOST_MISMATCH");Request.Builder request=new Request.Builder().url(url).header("User-Agent","IRAQhub/2.2 AndroidTV").header("Accept","application/json");if(token!=null&&!token.isEmpty())request.header("Authorization","Bearer "+token);if(body!=null)request.post(RequestBody.create(MediaType.parse("application/json; charset=utf-8"),body.toString()));try(Response response=HTTP.newCall(request.build()).execute()){if(response.code()>=300&&response.code()<400&&body==null&&token!=null&&!token.isEmpty()&&parsed.encodedPath().startsWith("/epgapi/")&&redirects<2){HttpUrl next=parsed.resolve(response.header("Location",""));if(next==null||!next.isHttps()||!next.username().isEmpty()||!next.password().isEmpty()||next.port()!=443||!next.encodedPath().equals(parsed.encodedPath())||!Objects.equals(next.encodedQuery(),parsed.encodedQuery())||!FactoryProtocol.allowedOrigin(saved,"https://"+next.host()))throw new IOException("FACTORY_REDIRECT_REJECTED");response.close();return request(next.toString(),token,null,redirects+1);}if(response.code()==401||response.code()==403)throw new IOException("FACTORY_AUTH_REQUIRED");if(!response.isSuccessful())throw new IOException("FACTORY_HTTP_"+response.code());try(InputStream in=response.body().byteStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("FACTORY_CANCELLED");if(out.size()+n>3*1024*1024)throw new IOException("FACTORY_RESPONSE_TOO_LARGE");out.write(bytes,0,n);}return new JSONObject(out.toString("UTF-8"));}}}
 private String query(String host,String path,Map<String,String> parameters)throws Exception{HttpUrl.Builder u=HttpUrl.parse(FactoryProtocol.origin(host)+path).newBuilder();for(Map.Entry<String,String> entry:parameters.entrySet())u.addQueryParameter(entry.getKey(),entry.getValue());return u.build().toString();}
 JSONObject authenticate(String user,String password,boolean force)throws Exception{synchronized(AUTH){saved=FactoryVault.read(context);identity=FactoryIdentity.read(context);if(!FactoryIdentity.valid(identity))throw new IOException("FACTORY_IDENTITY_REQUIRED");long now=System.currentTimeMillis();String token=saved.optString("accessToken");
  String host=saved.optString("host");if(host.isEmpty()||!saved.has("serviceOrigins")){Exception last=null;for(String address:DISCOVERY)try{Map<String,String> p=new LinkedHashMap<>();p.put("userid",identity.optString("sn"));for(String key:new String[]{"cid","pid","mid"})p.put(key,Integer.toString(identity.getInt(key)));HttpUrl.Builder url=HttpUrl.parse(address).newBuilder();for(Map.Entry<String,String> e:p.entrySet())url.addQueryParameter(e.getKey(),e.getValue());JSONObject discovery=request(url.build().toString(),"",null);host=FactoryProtocol.domain(discovery);saved.put("serviceOrigins",FactoryProtocol.origins(discovery));break;}catch(Exception e){last=e;}if(host.isEmpty())throw new IOException("FACTORY_DISCOVERY_UNAVAILABLE",last);saved.put("host",host);}else host=FactoryProtocol.origin(host);if(!force&&!token.isEmpty()&&saved.optLong("expiresAt")>now+30000){FactoryVault.save(context,saved);return saved;}
  JSONObject reply=null;if(!force&&!saved.optString("refreshToken").isEmpty()&&saved.optLong("refreshUntil")>now)try{reply=request(query(host,"/auth/v1/refresh",Collections.singletonMap("refreshToken",saved.optString("refreshToken"))),"",null);}catch(Exception ignored){}
  if(reply==null||reply.optInt("code",-1)!=0)reply=request(host+"/auth/v2/auth","",FactoryIdentity.payload(context,identity,user,password));JSONObject data=reply.optJSONObject("data");if(reply.optInt("code",-1)!=0||data==null)throw new IOException("FACTORY_LOGIN_REJECTED_"+reply.optInt("code",-1));String access=data.optString("accessToken");if(access.length()<16||access.length()>16384||access.contains("\n")||access.contains("\r"))throw new IOException("FACTORY_SESSION_INVALID");saved.put("accessToken",access);String issuedProfile=data.optString("chmaxProfile","");if(issuedProfile.length()>=8&&issuedProfile.length()<=24&&issuedProfile.matches("[A-Za-z0-9_-]+"))saved.put("chmaxProfile",issuedProfile);saved.put("refreshToken",data.optString("refreshToken"));saved.put("expiresAt",now+Math.max(60,Math.min(7*86400L,data.optLong("accessTokenTTL",3600)))*1000);saved.put("refreshUntil",now+Math.max(60,Math.min(30*86400L,data.optLong("refreshTokenTTL",86400)))*1000);FactoryVault.save(context,saved);return saved;
 }}
 synchronized JSONObject get(String path,Map<String,String> parameters)throws Exception{if(!Arrays.asList("/epgapi/v1/schedule/search","/epgapi/v1/schedule/list","/epgapi/v1/satellite/channel/list","/epgapi/v1/schedule/epgpro/getDesc").contains(path))throw new IOException("FACTORY_READ_ROUTE_REQUIRED");JSONObject session=authenticate("","",false);try{JSONObject reply=request(query(session.getString("host"),path,parameters),session.getString("accessToken"),null);if(reply.optInt("code",-1)!=0)throw new IOException("FACTORY_SERVICE_REJECTED_"+reply.optInt("code",-1));return reply;}catch(IOException failure){if("FACTORY_AUTH_REQUIRED".equals(failure.getMessage())){saved.put("expiresAt",0);FactoryVault.save(context,saved);}throw failure;}}
 static String safe(Exception e){for(Throwable t=e;t!=null;t=t.getCause()){if(t instanceof javax.net.ssl.SSLException)return "FACTORY_TLS_FAILED";if(t instanceof java.net.UnknownHostException)return "FACTORY_DNS_FAILED";if(t instanceof java.net.SocketTimeoutException||t instanceof java.io.InterruptedIOException)return "FACTORY_TIMEOUT";}String message=e.getMessage();return message!=null&&message.matches("FACTORY_[A-Z0-9_-]{1,60}")?message:"FACTORY_CONNECTION_FAILED";}
 /** CHL add-on uses the app's own authenticated session. Compatibility profile stays encrypted. */
 synchronized JSONArray channelIcons(JSONArray services)throws Exception{
  if(services.length()!=1)throw new IOException("FACTORY_SINGLE_SERVICE_REQUIRED");
  JSONObject session=authenticate("","",false);String profile=session.optString("chmaxProfile");
  if(profile.length()<8||profile.length()>24)throw new IOException("FACTORY_CHMAX_PROFILE_REQUIRED");
  JSONObject id=FactoryIdentity.read(context);String plain="sn="+id.getString("sn")+"&stbid=cid:"+id.getInt("cid")+";pid:"+id.getInt("pid")+";mid:"+id.getInt("mid")+"&chipid="+id.optString("chipId")+"&icon=1&name=full&hashType=png";
  RequestBody form=new MultipartBody.Builder().setType(MultipartBody.FORM).addFormDataPart("q",FactoryProtocol.authenticator(profile,plain)).addFormDataPart("sid",services.toString()).build();
  String url=FactoryProtocol.origin(session.getString("host"))+"/gchsapi/v1/chIconAndName";
  Request request=new Request.Builder().url(url).header("Authorization","Bearer "+session.getString("accessToken")).header("User-Agent","IRAQhub/2.4 AndroidTV").post(form).build();
  try(Response response=HTTP.newCall(request).execute()){
   if(response.code()==401||response.code()==403)throw new IOException("FACTORY_AUTH_REQUIRED");
   if(!response.isSuccessful())throw new IOException("FACTORY_HTTP_"+response.code());
   try(InputStream in=response.body().byteStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>3*1024*1024)throw new IOException("FACTORY_RESPONSE_TOO_LARGE");out.write(buf,0,n);}String text=out.toString("UTF-8").trim();if(text.startsWith("["))return new JSONArray(text);JSONObject j=new JSONObject(text);if(j.optInt("code",-1)!=0)throw new IOException("FACTORY_SERVICE_REJECTED_"+j.optInt("code",-1));JSONArray data=j.optJSONArray("data");return data==null?new JSONArray():data;}
  }
 }
 JSONObject identity()throws Exception{return FactoryIdentity.read(context);}
}
